-- SDS 2.1.1: 21 domain tables. Flyway's history table is infrastructure.
CREATE TABLE categories (id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,sort_order INT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE restaurants (id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,area_code VARCHAR(30) NOT NULL,address_text VARCHAR(255) NOT NULL,map_point_code VARCHAR(30) NOT NULL,image_code VARCHAR(80) NOT NULL,available BOOLEAN NOT NULL DEFAULT TRUE,sample_rating DECIMAL(2,1) NOT NULL DEFAULT 4.8,sample_distance_m INT NOT NULL DEFAULT 1200,sample_eta_minutes INT NOT NULL DEFAULT 25,sample_reviews_json JSON NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE users (id BIGINT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(80) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,display_name VARCHAR(100) NOT NULL,role VARCHAR(20) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,restaurant_id BIGINT NULL,driver_area_code VARCHAR(30) NULL,active_order_id BIGINT NULL UNIQUE,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(restaurant_id) REFERENCES restaurants(id),CHECK(role IN ('CUSTOMER','RESTAURANT','DRIVER')),CHECK((role='RESTAURANT' AND restaurant_id IS NOT NULL) OR (role<>'RESTAURANT' AND restaurant_id IS NULL)),CHECK(role='DRIVER' OR (driver_area_code IS NULL AND active_order_id IS NULL))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE auth_sessions (id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME(3) NOT NULL,revoked_at DATETIME(3) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE addresses (id BIGINT AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT NOT NULL,recipient_name VARCHAR(100) NOT NULL,recipient_phone CHAR(10) NOT NULL,area_code VARCHAR(30) NOT NULL,address_text VARCHAR(255) NOT NULL,label VARCHAR(40) NOT NULL,map_point_code VARCHAR(30) NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(customer_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE foods (id BIGINT AUTO_INCREMENT PRIMARY KEY,restaurant_id BIGINT NOT NULL,category_id BIGINT NOT NULL,name VARCHAR(150) NOT NULL,description TEXT NOT NULL,base_price BIGINT NOT NULL,kind VARCHAR(20) NOT NULL DEFAULT 'SINGLE',image_code VARCHAR(80) NOT NULL,available BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(restaurant_id) REFERENCES restaurants(id),FOREIGN KEY(category_id) REFERENCES categories(id),CHECK(base_price>=0),CHECK(kind IN ('SINGLE','COMBO')),INDEX ix_foods(restaurant_id,available,category_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE option_groups (id BIGINT AUTO_INCREMENT PRIMARY KEY,food_id BIGINT NOT NULL,name VARCHAR(80) NOT NULL,min_select INT NOT NULL,max_select INT NOT NULL,sort_order INT NOT NULL DEFAULT 0,FOREIGN KEY(food_id) REFERENCES foods(id),CHECK(min_select>=0 AND max_select>=min_select)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE option_values (id BIGINT AUTO_INCREMENT PRIMARY KEY,group_id BIGINT NOT NULL,name VARCHAR(80) NOT NULL,extra_price BIGINT NOT NULL,available BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(group_id) REFERENCES option_groups(id),UNIQUE(group_id,name),CHECK(extra_price>=0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE favorites (id BIGINT AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT NOT NULL,food_id BIGINT NULL,restaurant_id BIGINT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(customer_id) REFERENCES users(id),FOREIGN KEY(food_id) REFERENCES foods(id),FOREIGN KEY(restaurant_id) REFERENCES restaurants(id),UNIQUE(customer_id,food_id),UNIQUE(customer_id,restaurant_id),CHECK((food_id IS NULL)<>(restaurant_id IS NULL))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE carts (id BIGINT AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT NOT NULL UNIQUE,restaurant_id BIGINT NULL,version BIGINT NOT NULL DEFAULT 0,updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(customer_id) REFERENCES users(id),FOREIGN KEY(restaurant_id) REFERENCES restaurants(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE cart_items (id BIGINT AUTO_INCREMENT PRIMARY KEY,cart_id BIGINT NOT NULL,food_id BIGINT NOT NULL,quantity INT NOT NULL,note VARCHAR(200) NOT NULL DEFAULT '',signature_hash CHAR(64) NOT NULL,FOREIGN KEY(cart_id) REFERENCES carts(id),FOREIGN KEY(food_id) REFERENCES foods(id),UNIQUE(cart_id,signature_hash),CHECK(quantity BETWEEN 1 AND 99)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE cart_item_options (id BIGINT AUTO_INCREMENT PRIMARY KEY,cart_item_id BIGINT NOT NULL,option_value_id BIGINT NOT NULL,FOREIGN KEY(cart_item_id) REFERENCES cart_items(id) ON DELETE CASCADE,FOREIGN KEY(option_value_id) REFERENCES option_values(id),UNIQUE(cart_item_id,option_value_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE offers (id BIGINT AUTO_INCREMENT PRIMARY KEY,restaurant_id BIGINT NULL,code VARCHAR(40) NOT NULL UNIQUE,name VARCHAR(150) NOT NULL,kind VARCHAR(30) NOT NULL,percent INT NULL,amount BIGINT NULL,cap BIGINT NULL,min_subtotal BIGINT NOT NULL DEFAULT 0,required_method VARCHAR(30) NULL,starts_at DATETIME(3) NOT NULL,ends_at DATETIME(3) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(restaurant_id) REFERENCES restaurants(id),CHECK(min_subtotal>=0),CHECK(ends_at>starts_at),CHECK((kind='PERCENT' AND percent BETWEEN 1 AND 100 AND cap>=0) OR (kind='DELIVERY_DISCOUNT' AND amount>=0) OR kind='FREE_DELIVERY'),CHECK(required_method IS NULL OR required_method IN ('COD','MOCK_WALLET'))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE checkout_quotes (id BIGINT AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT NOT NULL,cart_id BIGINT NOT NULL,cart_version BIGINT NOT NULL,payload_json JSON NOT NULL,payload_hash CHAR(64) NOT NULL,expires_at DATETIME(3) NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(customer_id) REFERENCES users(id),FOREIGN KEY(cart_id) REFERENCES carts(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE orders (id BIGINT AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT NOT NULL,restaurant_id BIGINT NOT NULL,restaurant_name VARCHAR(150) NOT NULL,recipient_name VARCHAR(100) NOT NULL,recipient_phone CHAR(10) NOT NULL,area_code VARCHAR(30) NOT NULL,address_text VARCHAR(255) NOT NULL,map_point_code VARCHAR(30) NOT NULL,status VARCHAR(30) NOT NULL,payment_method VARCHAR(30) NOT NULL,payment_status VARCHAR(20) NOT NULL,subtotal BIGINT NOT NULL,delivery_fee BIGINT NOT NULL,food_discount BIGINT NOT NULL,delivery_discount BIGINT NOT NULL,total BIGINT NOT NULL,offer_snapshot_json JSON NULL,has_delivery_issue BOOLEAN NOT NULL DEFAULT FALSE,version BIGINT NOT NULL DEFAULT 0,driver_id BIGINT NULL,delivery_status VARCHAR(30) NOT NULL,dispatch_round INT NOT NULL DEFAULT 0,assigned_at DATETIME(3) NULL,picked_up_at DATETIME(3) NULL,delivered_at DATETIME(3) NULL,paid_at DATETIME(3) NULL,refunded_at DATETIME(3) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(customer_id) REFERENCES users(id),FOREIGN KEY(restaurant_id) REFERENCES restaurants(id),FOREIGN KEY(driver_id) REFERENCES users(id),CHECK(total=subtotal+delivery_fee-food_discount-delivery_discount),CHECK(subtotal>=0 AND delivery_fee>=0 AND food_discount>=0 AND delivery_discount>=0 AND total>=0),CHECK(status IN ('PENDING_CONFIRMATION','CONFIRMED','PREPARING','READY_FOR_PICKUP','OUT_FOR_DELIVERY','DELIVERED','CANCELLED','REJECTED')),CHECK(delivery_status IN ('NOT_STARTED','FINDING_DRIVER','NO_DRIVER','DRIVER_ASSIGNED','PICKED_UP','DELIVERED')),CHECK(payment_status IN ('UNPAID','PAID','REFUNDED')),CHECK(payment_method IN ('COD','MOCK_WALLET')),INDEX ix_customer_orders(customer_id,id),INDEX ix_restaurant_orders(restaurant_id,id),INDEX ix_driver_orders(driver_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
ALTER TABLE users ADD CONSTRAINT fk_users_active_order FOREIGN KEY(active_order_id) REFERENCES orders(id);
CREATE TABLE checkout_attempts (id BIGINT AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT NOT NULL,quote_id BIGINT NOT NULL,request_key CHAR(36) NOT NULL,request_hash CHAR(64) NOT NULL,method VARCHAR(30) NOT NULL,result VARCHAR(20) NOT NULL,scenario_code VARCHAR(40) NOT NULL,reason_code VARCHAR(50) NULL,order_id BIGINT NULL UNIQUE,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(customer_id) REFERENCES users(id),FOREIGN KEY(quote_id) REFERENCES checkout_quotes(id),FOREIGN KEY(order_id) REFERENCES orders(id),UNIQUE(customer_id,request_key),CHECK(result IN ('PENDING','SUCCEEDED','FAILED','CANCELLED','REFUNDED'))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE order_items (id BIGINT AUTO_INCREMENT PRIMARY KEY,order_id BIGINT NOT NULL,food_id BIGINT NOT NULL,food_name VARCHAR(150) NOT NULL,image_code VARCHAR(80) NOT NULL,base_price BIGINT NOT NULL,unit_price BIGINT NOT NULL,quantity INT NOT NULL,line_total BIGINT NOT NULL,note VARCHAR(200) NOT NULL,options_snapshot JSON NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(food_id) REFERENCES foods(id),CHECK(quantity BETWEEN 1 AND 99),CHECK(unit_price>=0 AND base_price>=0 AND line_total=unit_price*quantity)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE order_events (id BIGINT AUTO_INCREMENT PRIMARY KEY,order_id BIGINT NOT NULL,actor_id BIGINT NULL,event_type VARCHAR(40) NOT NULL,from_status VARCHAR(30) NULL,to_status VARCHAR(30) NULL,reason VARCHAR(300) NULL,client_request_key CHAR(36) NULL,payload_hash CHAR(64) NULL,related_event_id BIGINT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(actor_id) REFERENCES users(id),FOREIGN KEY(related_event_id) REFERENCES order_events(id),UNIQUE(actor_id,event_type,client_request_key),INDEX ix_events(order_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE driver_offers (id BIGINT AUTO_INCREMENT PRIMARY KEY,order_id BIGINT NOT NULL,driver_id BIGINT NOT NULL,round_no INT NOT NULL,status VARCHAR(20) NOT NULL,expires_at DATETIME(3) NOT NULL,responded_at DATETIME(3) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(driver_id) REFERENCES users(id),UNIQUE(order_id,round_no,driver_id),CHECK(status IN ('OFFERED','ACCEPTED','DECLINED','EXPIRED','REVOKED')),INDEX ix_driver_offers(driver_id,status,expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE messages (id BIGINT AUTO_INCREMENT PRIMARY KEY,order_id BIGINT NOT NULL,sender_id BIGINT NOT NULL,client_message_id CHAR(36) NOT NULL,kind VARCHAR(10) NOT NULL,text VARCHAR(1000) NULL,asset_code VARCHAR(80) NULL,is_simulated BOOLEAN NOT NULL DEFAULT FALSE,reply_to_message_id BIGINT NULL UNIQUE,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(sender_id) REFERENCES users(id),FOREIGN KEY(reply_to_message_id) REFERENCES messages(id),UNIQUE(sender_id,client_message_id),CHECK((kind='TEXT' AND text IS NOT NULL AND asset_code IS NULL) OR (kind='IMAGE' AND text IS NULL AND asset_code IS NOT NULL)),INDEX ix_messages(order_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE driver_reviews (id BIGINT AUTO_INCREMENT PRIMARY KEY,order_id BIGINT NOT NULL UNIQUE,customer_id BIGINT NOT NULL,driver_id BIGINT NOT NULL,stars INT NOT NULL,tags_json JSON NOT NULL,note VARCHAR(300) NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(customer_id) REFERENCES users(id),FOREIGN KEY(driver_id) REFERENCES users(id),CHECK(stars BETWEEN 1 AND 5)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
